// 미션 A1: 경보 임계값(0.01℃ 단위)을 75.00℃ 로 채우세요.
#include "task.h"
int32_t BMP280_ReadTempX100(void);
void UART_Send(const char *s);
#define TEMP_THRESHOLD_X100  /* ==== 여기에 코드를 작성하세요 ==== */
void vTask_TempAlarm(void *pvParameters)
{
    const TickType_t xPeriod = pdMS_TO_TICKS(100U);
    TickType_t xLastWakeTime = xTaskGetTickCount();
    for (;;)
    {
        int32_t lTempX100 = BMP280_ReadTempX100();
        if (lTempX100 > TEMP_THRESHOLD_X100)
        {
            UART_Send("ALARM");
        }
        vTaskDelayUntil(&xLastWakeTime, xPeriod);
    }
}

